package gen

import (
	"fmt"
	"math"
	"path"
	"regexp"
	"slices"
	"strconv"
	"strings"

	"github.com/WilkerSL/go-codebuild-tool/internal/naming"
	"github.com/WilkerSL/go-codebuild-tool/internal/schema"
)

// OpenAPIMarker is the value of the x-codebuild member that opens every
// generated openapi.json. JSON has no comments, so this member plays the role
// of the "Code generated" header that marks the file as codebuild's.
const OpenAPIMarker = "Code generated by codebuild. DO NOT EDIT."

// OpenAPIPath is where the document is written and served.
const OpenAPIPath = "openapi.json"

// openAPIDoc builds the OpenAPI 3.1 description of the REST API of pv. It is
// derived from the same domain and auth views that generate the handlers and
// routes, so the document follows the code instead of being kept next to it.
type openAPIDoc struct {
	pv      *projectView
	paths   object
	schemas object
	used    map[string]bool
	err     error
}

func openAPIDocument(pv *projectView) ([]byte, error) {
	d := &openAPIDoc{pv: pv}
	for _, dv := range pv.Domains {
		if dv.Routes || dv.IsAuth {
			d.entitySchemas(dv)
		}
		if dv.Routes {
			d.domainPaths(dv)
		}
	}
	if pv.Auth != nil {
		d.authPaths()
	}
	d.healthPaths()
	d.addSchema("ProblemDetails", problemSchema())
	d.addSchema("ProblemFieldError", object{}.
		set("type", "object").
		set("properties", object{}.
			set("field", object{}.set("type", "string")).
			set("message", object{}.set("type", "string"))).
		set("required", []string{"field", "message"}))
	if d.err != nil {
		return nil, d.err
	}
	components := object{}.
		set("schemas", d.schemas).
		set("parameters", d.parameters()).
		set("responses", errorResponses(d.used))
	doc := object{}.
		set("x-codebuild", OpenAPIMarker).
		set("openapi", "3.1.0").
		set("info", object{}.
			set("title", path.Base(pv.Module)).
			set("version", "1.0.0").
			set("description", "REST API generated by codebuild from the specs in specs/.")).
		set("servers", []object{object{}.set("url", "/").set("description", "The host that serves this document.")}).
		set("paths", d.paths)
	if pv.Auth != nil {
		components = components.set("securitySchemes", object{}.
			set("bearerAuth", object{}.
				set("type", "http").
				set("scheme", "bearer").
				set("description", "Send the access token, session token or API key as Authorization: Bearer <token>.")).
			set("cookieAuth", object{}.
				set("type", "apiKey").
				set("in", "cookie").
				set("name", pv.Auth.CredentialCookie).
				set("description", "HttpOnly cookie set by POST /auth/login for browser clients.")))
		doc = doc.set("security", securityRequirement())
	} else {
		doc = doc.set("security", []object{})
	}
	return indentDocument(doc.set("components", components))
}

func securityRequirement() []object {
	return []object{object{}.set("bearerAuth", []string{}), object{}.set("cookieAuth", []string{})}
}

func (d *openAPIDoc) addSchema(name string, s object) {
	if d.schemas.get(name) != nil {
		if d.err == nil {
			d.err = fmt.Errorf("openapi: two schemas are named %s; rename the entity", name)
		}
		return
	}
	d.schemas = d.schemas.set(name, s)
}

func (d *openAPIDoc) addOperation(route, method string, op object) {
	item, _ := d.paths.get(route).(object)
	d.paths = d.paths.set(route, item.set(strings.ToLower(method), op))
}

func schemaRef(name string) object {
	return object{}.set("$ref", "#/components/schemas/"+name)
}

func jsonContent(schema object) object {
	return object{}.set("application/json", object{}.set("schema", schema))
}

func (d *openAPIDoc) entitySchemas(dv *domainView) {
	props, required := object{}, []string{}
	for _, fv := range dv.Fields {
		if fv.F.OmitResponse {
			continue
		}
		props = props.set(fv.F.JSON, fieldSchema(fv.F, fv.F.Nullable))
		required = append(required, fv.F.JSON)
	}
	d.addSchema(dv.Name, object{}.set("type", "object").set("properties", props).set("required", required))
	if !dv.Routes {
		return
	}
	d.addSchema(dv.Name+"Page", object{}.
		set("type", "object").
		set("properties", object{}.
			set("items", object{}.set("type", "array").set("items", schemaRef(dv.Name))).
			set("limit", object{}.set("type", "integer")).
			set("offset", object{}.set("type", "integer")).
			set("total", object{}.set("type", "integer").set("format", "int64").set("description", "Number of rows matching the filters; only on offset pages.")).
			set("nextCursor", object{}.set("type", []string{"string", "null"}).set("description", "Pass as ?cursor= to get the next page; null on the last page."))).
		set("required", []string{"items", "limit", "offset", "nextCursor"}))
	if !dv.ReadOnly {
		d.addSchema(dv.Name+"Create", inputSchema(dv.Create, dv.RequiredCreate, true))
		if dv.HasUpdate {
			d.addSchema(dv.Name+"Update", inputSchema(dv.Update, dv.RequiredUpdate, false))
		}
	}
}

func inputSchema(fields, required []*fieldView, create bool) object {
	props := object{}
	for _, fv := range fields {
		s := fieldSchema(fv.F, fv.F.Nullable)
		if create && fv.F.HasDefault {
			if v, ok := defaultValue(fv.F); ok {
				s = s.set("default", v)
			}
		}
		props = props.set(fv.F.InputJSON(), s)
	}
	names := []string{}
	for _, fv := range required {
		names = append(names, fv.F.InputJSON())
	}
	return object{}.
		set("type", "object").
		set("properties", props).
		set("required", names).
		set("additionalProperties", false)
}

func defaultValue(f *schema.Field) (any, bool) {
	switch {
	case f.Kind == schema.KindBool:
		b, err := strconv.ParseBool(f.Default)
		return b, err == nil
	case f.Kind.IsInteger():
		n, err := strconv.ParseInt(f.Default, 10, 64)
		return n, err == nil
	case f.Kind == schema.KindFloat32 || f.Kind == schema.KindFloat64:
		n, err := strconv.ParseFloat(f.Default, 64)
		return n, err == nil
	case f.Kind == schema.KindString:
		return f.Default, true
	}
	return nil, false
}

func fieldSchema(f *schema.Field, nullable bool) object {
	s := object{}
	kind, format := "", ""
	switch f.Kind {
	case schema.KindString:
		kind = "string"
	case schema.KindBool:
		kind = "boolean"
	case schema.KindInt16, schema.KindInt32:
		kind, format = "integer", "int32"
	case schema.KindInt, schema.KindInt64:
		kind, format = "integer", "int64"
	case schema.KindFloat32:
		kind, format = "number", "float"
	case schema.KindFloat64:
		kind, format = "number", "double"
	case schema.KindBytes:
		kind = "string"
	case schema.KindTime:
		kind, format = "string", "date-time"
	case schema.KindUUID:
		kind, format = "string", "uuid"
	}
	if nullable {
		s = s.set("type", []string{kind, "null"})
	} else {
		s = s.set("type", kind)
	}
	if f.Email {
		format = "email"
	}
	if format != "" {
		s = s.set("format", format)
	}
	var notes []string
	switch {
	case f.Kind == schema.KindString:
		if f.Min != "" {
			s = s.set("minLength", atoi(f.Min))
		}
		if limit := fieldMax(f); limit != "" {
			s = s.set("maxLength", atoi(limit))
		}
		if f.NotEmpty {
			s = s.set("pattern", `\S`)
		}
		if len(f.Enum) > 0 {
			s = s.set("enum", f.Enum)
		}
	case f.Kind == schema.KindBytes:
		s = s.set("contentEncoding", "base64")
		if f.Min != "" {
			notes = append(notes, "at least "+f.Min+" bytes")
		}
		if f.Max != "" {
			notes = append(notes, "at most "+f.Max+" bytes")
		}
		if f.NotEmpty {
			notes = append(notes, "not empty")
		}
	case f.Kind.IsNumeric():
		lo, hi := f.Min, f.Max
		if f.Kind == schema.KindInt16 {
			lo, hi = cmpOr(lo, "-32768"), cmpOr(hi, "32767")
		}
		if lo != "" {
			s = s.set("minimum", number(lo))
		}
		if hi != "" {
			s = s.set("maximum", number(hi))
		}
	}
	if f.Ref != nil && f.Ref.Target != nil {
		notes = append(notes, "references a "+f.Ref.Target.Name)
	}
	if len(notes) > 0 {
		s = s.set("description", capitalizeFirst(strings.Join(notes, "; "))+".")
	}
	return s
}

func cmpOr(v, fallback string) string {
	if v != "" {
		return v
	}
	return fallback
}

func atoi(s string) int {
	n, _ := strconv.Atoi(s)
	return n
}

func number(s string) any {
	if n, err := strconv.ParseInt(s, 10, 64); err == nil {
		return n
	}
	f, _ := strconv.ParseFloat(s, 64)
	return f
}

func capitalizeFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

func problemSchema() object {
	return object{}.
		set("type", "object").
		set("description", "RFC 9457 problem details.").
		set("properties", object{}.
			set("type", object{}.set("type", "string")).
			set("title", object{}.set("type", "string")).
			set("status", object{}.set("type", "integer")).
			set("detail", object{}.set("type", "string")).
			set("instance", object{}.set("type", "string")).
			set("errors", object{}.set("type", "array").set("items", schemaRef("ProblemFieldError")))).
		set("required", []string{"type", "title", "status"})
}

var problemStatuses = []struct {
	name, code, description string
}{
	{"BadRequest", "400", "The request is malformed: invalid JSON, unknown members or invalid query parameters."},
	{"Unauthorized", "401", "Authentication is required or the credential is invalid."},
	{"Forbidden", "403", "The caller is not allowed to perform this operation."},
	{"NotFound", "404", "The resource does not exist or belongs to another owner."},
	{"Conflict", "409", "A unique value is already taken, or the resource is still referenced."},
	{"PayloadTooLarge", "413", "The request body is larger than 1 MiB."},
	{"UnsupportedMediaType", "415", "The request body was not sent with Content-Type: application/json."},
	{"UnprocessableEntity", "422", "Validation failed; errors lists every invalid field."},
	{"TooManyRequests", "429", "Too many attempts; retry after the number of seconds in Retry-After."},
	{"ServiceUnavailable", "503", "The service is shutting down or a backend is unreachable."},
	{"Error", "default", "Unexpected error."},
}

func errorResponses(used map[string]bool) object {
	out := object{}
	for _, p := range problemStatuses {
		if !used[p.name] {
			continue
		}
		r := object{}.
			set("description", p.description).
			set("content", object{}.set("application/problem+json", object{}.set("schema", schemaRef("ProblemDetails"))))
		switch p.code {
		case "401":
			r = r.set("headers", object{}.set("WWW-Authenticate", object{}.set("schema", object{}.set("type", "string"))))
		case "429":
			r = r.set("headers", object{}.set("Retry-After", object{}.set("schema", object{}.set("type", "integer"))))
		}
		out = out.set(p.name, r)
	}
	return out
}

func (d *openAPIDoc) parameters() object {
	p := d.pv.Pagination
	return object{}.
		set("Limit", object{}.
			set("name", "limit").
			set("in", "query").
			set("description", "Maximum number of items on the page.").
			set("schema", object{}.set("type", "integer").set("minimum", 1).set("maximum", p.MaxLimit).set("default", p.DefaultLimit))).
		set("Offset", object{}.
			set("name", "offset").
			set("in", "query").
			set("description", "Number of items to skip. Cannot be combined with cursor.").
			set("schema", object{}.set("type", "integer").set("minimum", 0).set("maximum", math.MaxInt32).set("default", 0))).
		set("Cursor", object{}.
			set("name", "cursor").
			set("in", "query").
			set("description", "The nextCursor of the previous page. Cursor pages are not counted, so they have no total.").
			set("schema", object{}.set("type", "string")))
}

// opBuilder collects one operation; responses are kept by status code and
// written in ascending order with the default response last.
type opBuilder struct {
	op        object
	responses map[string]any
	used      map[string]bool
}

func (d *openAPIDoc) newOp(id, summary, tag string) *opBuilder {
	if d.used == nil {
		d.used = map[string]bool{}
	}
	return &opBuilder{op: object{}.set("operationId", id).set("summary", summary).set("tags", []string{tag}), responses: map[string]any{}, used: d.used}
}

func (b *opBuilder) respond(code string, r any) *opBuilder {
	b.responses[code] = r
	return b
}

func (b *opBuilder) problems(names ...string) *opBuilder {
	for _, name := range names {
		for _, p := range problemStatuses {
			if p.name == name {
				b.used[name] = true
				b.responses[p.code] = object{}.set("$ref", "#/components/responses/"+name)
			}
		}
	}
	return b
}

func (b *opBuilder) body(schema string, required bool) *opBuilder {
	b.op = b.op.set("requestBody", object{}.set("required", required).set("content", jsonContent(schemaRef(schema))))
	return b.problems("PayloadTooLarge", "UnsupportedMediaType")
}

func (b *opBuilder) params(params ...any) *opBuilder {
	if len(params) > 0 {
		existing, _ := b.op.get("parameters").([]any)
		b.op = b.op.set("parameters", append(existing, params...))
	}
	return b
}

// guard applies the access policy of the operation: public operations clear
// the document-wide security requirement, protected ones can answer 401 and,
// when they need roles, 403.
func (b *opBuilder) guard(guarded bool, policy schema.Policy) *opBuilder {
	if !guarded {
		return b
	}
	if policy.Public {
		b.op = b.op.set("security", []object{})
		return b
	}
	b.problems("Unauthorized")
	if len(policy.Roles) > 0 {
		b.op = b.op.set("description", "Requires one of the roles: "+strings.Join(policy.Roles, ", ")+".")
		b.problems("Forbidden")
	}
	return b
}

func (b *opBuilder) build() object {
	codes := make([]string, 0, len(b.responses))
	for code := range b.responses {
		codes = append(codes, code)
	}
	slices.SortFunc(codes, func(x, y string) int {
		if x == "default" {
			return 1
		}
		if y == "default" {
			return -1
		}
		return strings.Compare(x, y)
	})
	responses := object{}
	for _, code := range codes {
		responses = responses.set(code, b.responses[code])
	}
	return b.op.set("responses", responses)
}

func refParam(name string) object {
	return object{}.set("$ref", "#/components/parameters/"+name)
}

func pathParam(name string, f *schema.Field) object {
	return object{}.set("name", name).set("in", "path").set("required", true).set("schema", fieldSchema(f, false))
}

var pathParamPattern = regexp.MustCompile(`\{([A-Za-z0-9_]+)\}`)

// routeParams declares the path parameters of route in order, taking their
// schemas from the fields that the route uses for them.
func routeParams(route string, fields ...*schema.Field) []any {
	var out []any
	for i, m := range pathParamPattern.FindAllStringSubmatch(route, -1) {
		if i < len(fields) {
			out = append(out, pathParam(m[1], fields[i]))
		}
	}
	return out
}

func okResponse(description, schema string) object {
	r := object{}.set("description", description)
	if schema != "" {
		r = r.set("content", jsonContent(schemaRef(schema)))
	}
	return r
}

func createdResponse(schema string) object {
	return object{}.
		set("description", "Created.").
		set("headers", object{}.set("Location", object{}.set("description", "URL of the new resource.").set("schema", object{}.set("type", "string")))).
		set("content", jsonContent(schemaRef(schema)))
}

func (d *openAPIDoc) filterParams(dv *domainView, skip *schema.Field) []any {
	var out []any
	for _, fv := range dv.Filters {
		if fv.F == skip {
			continue
		}
		out = append(out, object{}.
			set("name", fv.F.JSON).
			set("in", "query").
			set("description", "Only items whose "+fv.F.JSON+" equals this value.").
			set("schema", fieldSchema(fv.F, false)))
	}
	return out
}

func hasUnique(e *schema.Entity) bool {
	return slices.ContainsFunc(e.Fields, func(f *schema.Field) bool { return f.Unique && !f.PK })
}

func (d *openAPIDoc) domainPaths(dv *domainView) {
	e := dv.Entity
	tag := dv.Package
	plural := naming.Pascal(e.Table)
	guarded := dv.Guarded
	pagination := []any{refParam("Limit"), refParam("Offset"), refParam("Cursor")}

	list := d.newOp("list"+plural, "List "+dv.Nouns, tag).
		params(pagination...).params(d.filterParams(dv, nil)...).
		respond("200", okResponse("A page of "+dv.Nouns+".", dv.Name+"Page")).
		problems("BadRequest", "Error").
		guard(guarded, e.Policy(schema.OpRead))
	d.addOperation(dv.Path, "GET", list.build())
	if !e.ReadOnly {
		create := d.newOp("create"+dv.Name, "Create a "+dv.Noun, tag).
			body(dv.Name+"Create", true).
			respond("201", createdResponse(dv.Name)).
			problems("BadRequest", "UnprocessableEntity", "Error").
			guard(guarded, e.Policy(schema.OpCreate))
		if hasUnique(e) {
			create.problems("Conflict")
		}
		d.addOperation(dv.Path, "POST", create.build())
	}
	id := routeParams(dv.ItemPath, e.PK())
	get := d.newOp("get"+dv.Name, "Get a "+dv.Noun, tag).
		params(id...).
		respond("200", okResponse("The "+dv.Noun+".", dv.Name)).
		problems("BadRequest", "NotFound", "Error").
		guard(guarded, e.Policy(schema.OpRead))
	d.addOperation(dv.ItemPath, "GET", get.build())
	if dv.HasUpdate {
		update := d.newOp("update"+dv.Name, "Replace a "+dv.Noun, tag).
			params(id...).
			body(dv.Name+"Update", true).
			respond("200", okResponse("The updated "+dv.Noun+".", dv.Name)).
			problems("BadRequest", "NotFound", "UnprocessableEntity", "Error").
			guard(guarded, e.Policy(schema.OpUpdate))
		if hasUnique(e) {
			update.problems("Conflict")
		}
		d.addOperation(dv.ItemPath, "PUT", update.build())
	}
	if !e.ReadOnly {
		del := d.newOp("delete"+dv.Name, "Delete a "+dv.Noun, tag).
			params(id...).
			respond("204", object{}.set("description", "Deleted.")).
			problems("BadRequest", "NotFound", "Error").
			guard(guarded, e.Policy(schema.OpDelete))
		if dv.HasRestrict {
			del.problems("Conflict")
		}
		d.addOperation(dv.ItemPath, "DELETE", del.build())
	}
	for _, rv := range dv.Relations {
		listPolicy, linkPolicy, _ := schema.RelationPolicies(rv.Source, e, schema.RelationKind(rv.Kind))
		var skip *schema.Field
		if rv.FK != nil {
			skip = rv.FK.F
		}
		source := routeParams(rv.Path, rv.Source.PK())
		relation := strings.TrimPrefix(rv.Method, "List"+rv.Source.Name)
		rel := d.newOp("list"+relation+"Of"+rv.Source.Name, "List the "+dv.Nouns+" of a "+noun(rv.Source.Name), tag).
			params(source...).params(pagination...).params(d.filterParams(dv, skip)...).
			respond("200", okResponse("A page of "+dv.Nouns+".", dv.Name+"Page")).
			problems("BadRequest", "Error").
			guard(guarded, listPolicy)
		if !rv.ExternalSource {
			rel.problems("NotFound")
		}
		d.addOperation(rv.Path, "GET", rel.build())
		if rv.Writable {
			both := routeParams(rv.ItemPath, rv.Source.PK(), e.PK())
			link := d.newOp(rv.LinkHandler, "Link a "+dv.Noun+" to a "+noun(rv.Source.Name), tag).
				params(both...).
				respond("204", object{}.set("description", "Linked; linking twice is not an error.")).
				problems("BadRequest", "NotFound", "Error").
				guard(guarded, linkPolicy)
			d.addOperation(rv.ItemPath, "PUT", link.build())
			unlink := d.newOp(rv.UnlinkHandler, "Unlink a "+dv.Noun+" from a "+noun(rv.Source.Name), tag).
				params(both...).
				respond("204", object{}.set("description", "Unlinked; unlinking twice is not an error.")).
				problems("BadRequest", "NotFound", "Error").
				guard(guarded, linkPolicy)
			d.addOperation(rv.ItemPath, "DELETE", unlink.build())
		}
	}
}

func (d *openAPIDoc) authDomain() *domainView {
	for _, dv := range d.pv.Domains {
		if dv.Entity == d.pv.Auth.Entity {
			return dv
		}
	}
	return nil
}

func (d *openAPIDoc) authPaths() {
	a := d.pv.Auth
	dv := d.authDomain()
	if dv == nil {
		return
	}
	public := schema.Policy{Public: true}
	logged := schema.Policy{}
	tokens := object{}.
		set("accessToken", object{}.set("type", "string")).
		set("tokenType", object{}.set("type", "string").set("enum", []string{"Bearer"})).
		set("expiresAt", object{}.set("type", "string").set("format", "date-time"))
	tokenFields := []string{"accessToken", "tokenType", "expiresAt"}
	if a.JWT {
		tokens = tokens.
			set("refreshToken", object{}.set("type", "string")).
			set("refreshExpiresAt", object{}.set("type", "string").set("format", "date-time"))
		tokenFields = append(tokenFields, "refreshToken", "refreshExpiresAt")
	}
	d.addSchema("AuthTokens", object{}.set("type", "object").set("properties", tokens).set("required", tokenFields))
	identity := fieldSchema(a.Identity.F, false)
	identity = identity.set("maxLength", atoi(a.IdentityMax))
	d.addSchema("AuthLogin", object{}.
		set("type", "object").
		set("properties", object{}.
			set(a.Identity.InputJSON, identity).
			set(a.Password.InputJSON, object{}.set("type", "string").set("minLength", 1))).
		set("required", []string{a.Identity.InputJSON, a.Password.InputJSON}).
		set("additionalProperties", false))
	password := fieldSchema(a.Password.F, false)
	d.addSchema("AuthPasswordChange", object{}.
		set("type", "object").
		set("properties", object{}.
			set("currentPassword", object{}.set("type", "string")).
			set("newPassword", password)).
		set("required", []string{"currentPassword", "newPassword"}).
		set("additionalProperties", false))
	tokensOK := okResponse("The issued credentials; they are also set as HttpOnly cookies.", "AuthTokens")

	if a.Register {
		var fields, required []*fieldView
		for _, fv := range dv.Create {
			if !fv.F.Role {
				fields = append(fields, fv)
			}
		}
		for _, fv := range dv.RequiredCreate {
			if !fv.F.Role {
				required = append(required, fv)
			}
		}
		d.addSchema("AuthRegister", inputSchema(fields, required, true))
		register := d.newOp("authRegister", "Create an account", "auth").
			body("AuthRegister", true).
			respond("201", createdResponse(dv.Name)).
			problems("BadRequest", "Conflict", "UnprocessableEntity", "TooManyRequests", "Error").
			guard(true, public)
		d.addOperation("/auth/register", "POST", register.build())
	}
	login := d.newOp("authLogin", "Log in", "auth").
		body("AuthLogin", true).
		respond("200", tokensOK).
		problems("BadRequest", "Unauthorized", "UnprocessableEntity", "TooManyRequests", "Error").
		guard(true, public)
	d.addOperation("/auth/login", "POST", login.build())
	if a.JWT {
		d.addSchema("AuthRefresh", object{}.
			set("type", "object").
			set("properties", object{}.set("refreshToken", object{}.set("type", "string"))).
			set("additionalProperties", false))
		refresh := d.newOp("authRefresh", "Rotate the refresh token", "auth").
			body("AuthRefresh", false).
			respond("200", tokensOK).
			problems("BadRequest", "Unauthorized", "Forbidden", "Error").
			guard(true, public)
		refresh.op = refresh.op.set("description", "Send the refresh token in the body, or rely on the refresh_token cookie.")
		d.addOperation("/auth/refresh", "POST", refresh.build())
	}
	logout := d.newOp("authLogout", "Log out", "auth").
		respond("204", object{}.set("description", "The session or refresh token family is revoked and the cookies are cleared.")).
		problems("BadRequest", "Error").
		guard(true, logged)
	d.addOperation("/auth/logout", "POST", logout.build())
	me := d.newOp("authMe", "Get the account of the caller", "auth").
		respond("200", okResponse("The account.", dv.Name)).
		problems("Error").
		guard(true, logged)
	d.addOperation("/auth/me", "GET", me.build())
	change := d.newOp("authChangePassword", "Change the password", "auth").
		body("AuthPasswordChange", true).
		respond("204", object{}.set("description", "Changed; every other session or refresh token family is revoked.")).
		problems("BadRequest", "Forbidden", "UnprocessableEntity", "TooManyRequests", "Error").
		guard(true, logged)
	d.addOperation("/auth/password", "PUT", change.build())
	if a.APIKey {
		key := object{}.
			set("id", object{}.set("type", "string")).
			set("name", object{}.set("type", "string")).
			set("prefix", object{}.set("type", "string")).
			set("createdAt", object{}.set("type", "string").set("format", "date-time")).
			set("expiresAt", object{}.set("type", []string{"string", "null"}).set("format", "date-time"))
		keyFields := []string{"id", "name", "prefix", "createdAt", "expiresAt"}
		d.addSchema("AuthAPIKey", object{}.set("type", "object").set("properties", key).set("required", keyFields))
		d.addSchema("AuthAPIKeyCreated", object{}.
			set("type", "object").
			set("properties", slices.Clone(key).set("key", object{}.set("type", "string").set("description", "The API key; it is returned only once."))).
			set("required", append(slices.Clone(keyFields), "key")))
		d.addSchema("AuthAPIKeyCreate", object{}.
			set("type", "object").
			set("properties", object{}.
				set("name", object{}.set("type", "string").set("minLength", 1).set("maxLength", 120).set("pattern", `\S`)).
				set("expiresAt", object{}.set("type", []string{"string", "null"}).set("format", "date-time"))).
			set("required", []string{"name"}).
			set("additionalProperties", false))
		d.addSchema("AuthAPIKeyList", object{}.
			set("type", "object").
			set("properties", object{}.set("items", object{}.set("type", "array").set("items", schemaRef("AuthAPIKey")))).
			set("required", []string{"items"}))
		createKey := d.newOp("authCreateAPIKey", "Create an API key", "auth").
			body("AuthAPIKeyCreate", true).
			respond("201", createdResponse("AuthAPIKeyCreated")).
			problems("BadRequest", "Forbidden", "Conflict", "UnprocessableEntity", "Error").
			guard(true, logged)
		d.addOperation("/auth/api-keys", "POST", createKey.build())
		listKeys := d.newOp("authListAPIKeys", "List the API keys of the caller", "auth").
			respond("200", okResponse("The API keys, without their secret.", "AuthAPIKeyList")).
			problems("Forbidden", "Error").
			guard(true, logged)
		d.addOperation("/auth/api-keys", "GET", listKeys.build())
		deleteKey := d.newOp("authDeleteAPIKey", "Delete an API key", "auth").
			params(object{}.set("name", "id").set("in", "path").set("required", true).set("schema", object{}.set("type", "string"))).
			respond("204", object{}.set("description", "Deleted.")).
			problems("BadRequest", "Forbidden", "NotFound", "Error").
			guard(true, logged)
		d.addOperation("/auth/api-keys/{id}", "DELETE", deleteKey.build())
	}
}

func (d *openAPIDoc) healthPaths() {
	guarded := d.pv.Auth != nil
	status := func(value string) object {
		return object{}.
			set("type", "object").
			set("properties", object{}.set("status", object{}.set("type", "string").set("enum", []string{value}))).
			set("required", []string{"status"})
	}
	live := d.newOp("livez", "Liveness probe", "health").
		respond("200", object{}.set("description", "The process is running.").set("content", jsonContent(status("ok")))).
		guard(guarded, schema.Policy{Public: true})
	d.addOperation("/livez", "GET", live.build())
	ready := d.newOp("readyz", "Readiness probe", "health").
		respond("200", object{}.set("description", "The service accepts traffic.").set("content", jsonContent(status("ready")))).
		problems("ServiceUnavailable").
		guard(guarded, schema.Policy{Public: true})
	d.addOperation("/readyz", "GET", ready.build())
}

// rawLiteral quotes s as a Go string literal with exactly the same bytes, so the
// embedded document is identical to openapi.json.
func rawLiteral(s string) string {
	if strings.Contains(s, "`") {
		return strconv.Quote(s)
	}
	return "`" + s + "`"
}

type openAPIView struct {
	Header  string
	Literal string
}

// openAPI writes openapi.json at the project root and embeds the same bytes in
// the app package, which serves them at GET /openapi.json.
func (g *generator) openAPI(pv *projectView) {
	if g.err != nil {
		return
	}
	doc, err := openAPIDocument(pv)
	if err != nil {
		g.err = err
		return
	}
	g.files = append(g.files, File{Path: OpenAPIPath, Content: doc, Owner: OwnerGenerated})
	g.goFile("internal/app/openapi_gen.go", "project/openapi.go.tmpl", openAPIView{Header: Header, Literal: rawLiteral(string(doc))})
}
